<?php require_once __DIR__.'/../api/bootstrap.php';require_login();$m=current_medico();$id=(int)($_GET['id']??0);$p=patient_for_doctor($id,$m['id']);if(!$p)exit('Paciente não encontrado.');$err='';$fields=['nome','cpf','data_nascimento','sexo','telefone','email','endereco','profissao','funcao','empresa','info_clinica','alergias','medicamentos','antecedentes'];if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$v=[];foreach($fields as $f)$v[$f]=trim($_POST[$f]??'');if($v['nome']==='')$err='Nome é obrigatório.';else{$q=db()->prepare('UPDATE pacientes SET nome=?,cpf=?,data_nascimento=?,sexo=?,telefone=?,email=?,endereco=?,profissao=?,funcao=?,empresa=?,info_clinica=?,alergias=?,medicamentos=?,antecedentes=? WHERE id=? AND medico_id=?');$q->execute([...array_values($v),$id,$m['id']]);audit_log('editar_paciente','pacientes',$id);header('Location:index.php');exit;}}render_header('Editar paciente');?><h1>Editar paciente</h1><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="card"><div class="grid"><?php foreach([['nome','Nome completo'],['cpf','CPF'],['data_nascimento','Data de nascimento'],['telefone','Telefone'],['email','E-mail'],['profissao','Profissão'],['funcao','Função/atividade'],['empresa','Empresa'],['endereco','Endereço']] as $f):?><div><label><?=e($f[1])?></label><input name="<?=$f[0]?>" value="<?=e($p[$f[0]])?>" <?=$f[0]==='data_nascimento'?'type="date"':''?>></div><?php endforeach;?></div><label>Informações clínicas</label><textarea name="info_clinica"><?=e($p['info_clinica'])?></textarea><div class="grid"><div><label>Alergias</label><textarea name="alergias"><?=e($p['alergias'])?></textarea></div><div><label>Medicamentos em uso</label><textarea name="medicamentos"><?=e($p['medicamentos'])?></textarea></div></div><label>Antecedentes</label><textarea name="antecedentes"><?=e($p['antecedentes'])?></textarea></div><button class="btn">Salvar</button></form><?php render_footer();?>